'use strict';

const { planFare } = require('./services/booking');
const { quoteDriver, reconcileWash, scheduleLine } = require('./services/dispatch');
const quotes = require('./services/quotes');
const billing = require('./services/billing');
const steps = require('./util/steps');

/** Run the Tramyard report for a batch size and a number of days. */
function run(count, days) {
  let r1 = planFare(count, count);
  let r2 = reconcileWash(count + 6, count);
  let r3 = scheduleLine(Math.max(r1 - 2, 0), count);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = quoteDriver(r3, count);
  let r5 = quotes.checkPantograph(r2 + 1);
  let r6 = quotes.checkRoute(r5);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = billing.scheduleDriver(r6, r4 + 8);
  let r8 = billing.priceTram(r5, r3);
  let r9 = billing.assembleBay(days + 2);
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = billing.auditShift(days, Math.max(r7 - 4, 0));
  console.log(`batch 4: ${r10} ${r9}`);
  let shift = steps.scaleRoster(count);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + shift) % 10007;
  console.log(`tramyard total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

