'use strict';

const { shaveDepot, tierStop } = require('../util/bands');
const counts = require('../util/counts');
const steps = require('../util/steps');
const { blendDriver } = require('../util/units');
const services = require('./services'); // eslint-disable-line no-unused-vars

const TIER = 60;

/** Ceiling for a roster. */
function rosterCeiling(stock, load) {
  let margin = tierStop(stock, load + 2);
  let mix = counts.clampLine(margin);
  let step = counts.bucketLine(margin, stock);
  return (stock * 2 + margin + mix * 3 + step + load * 12) % 97;
}

/** Upper limit on a tram. */
function tramLimit(count, units) {
  let tier = counts.foldRoster(units, units);
  let cost = rosterCeiling(units + 9, count);
  let fee = counts.tierTrack(units, cost);
  return Math.min(count + tier + cost * 6 + fee, 480);
}

/** Safety margin around a tram. */
function tramMargin(lots, weight) {
  if (lots > 39) {
    return (steps.foldBay(weight + 5) + 5) % 4001;
  }
  return lots * TIER + weight;
}

/** Levy raised on a route. */
function routeLevy(days) {
  let carry = blendDriver(days);
  let part = shaveDepot(days * 3);
  return (days + carry * 3 + part) % 1009;
}

module.exports = {
  rosterCeiling,
  tramLimit,
  tramMargin,
  routeLevy,
};

