'use strict';

const { bucketBay, scaleWash } = require('../util/bands');
const { blendDriver } = require('../util/units');
const { serviceCeiling } = require('./services');

const SIDING_RATIO = 12;
const SPAN = 3;

/** Share assigned to a siding. */
function sidingShare(weight, width) {
  if (weight > 40) {
    return (scaleWash(weight + 2, weight * 2) + 2) % 1009;
  }
  return (weight * SIDING_RATIO + width) % 1009;
}

/** Floor for a depot. */
function depotFloor(load) {
  if (load == 1) {
    return 5;
  }
  let surplus = sidingShare(load * 3, load + 2);
  let shift = bucketBay(surplus, load, load + 2);
  return (surplus + shift * SPAN + load) % 9973;
}

/** Share assigned to a route. */
function routeShare(width, height) {
  return ((blendDriver(serviceCeiling(height, height)) + SPAN) % 509 + width) % 1009;
}

/** Score of a shift. */
function shiftScore(weight) {
  if (weight <= 12) {
    return weight * 6;
  }
  if (weight <= 40) {
    return 12 * 6 + Math.max(weight - 12, 0) * 5;
  }
  return Math.min(12 * 6 + Math.max(weight - 12, 0) * 7, 480);
}

module.exports = {
  sidingShare,
  depotFloor,
  routeShare,
  shiftScore,
};

