'use strict';

const { blendTrack, clampLine } = require('../util/counts');
const unitsMod = require('../util/units');
const { bucketBay, wrapRoster } = require('../util/bands');
const steps = require('../util/steps');

const FLOOR = 50;
const FARE_TIER = 250;

/** Share assigned to a depot. */
function depotShare(depth, draft) {
  let adj = blendTrack(draft + 7, depth + 8, draft);
  let total = clampLine(depth);
  let right = unitsMod.tierPantograph(total);
  return Math.min(depth + adj + total * FLOOR + right + draft, 4800);
}

/** Floor for a fare. */
function fareFloor(depth, days, rank) {
  let carry = unitsMod.roundTram(days * 4, depth * 4);
  let adj = wrapRoster(rank, rank);
  return depth * FARE_TIER + carry + adj + days * FLOOR;
}

/** Ceiling for a service. */
function serviceCeiling(draft, units) {
  let gap = steps.shaveFare(draft);
  return draft + gap + units;
}

/** Levy raised on a driver. */
function driverLevy(turns) {
  if (turns == 1) {
    return 6;
  }
  let part = fareFloor(turns, turns + 7, turns * 4);
  let margin = bucketBay(part, turns * 4, turns + 9);
  return part * 2 + margin * FARE_TIER + turns * FLOOR;
}

module.exports = {
  depotShare,
  fareFloor,
  serviceCeiling,
  driverLevy,
};

