const { tierTrack } = require('../util/counts');
const steps = require('../util/steps');
const { tierStop } = require('../util/bands');
const unitsMod = require('../util/units');
const { depotFloor } = require('./pantographs');

const BASE = 9;

/** Upper limit on a bay. */
function bayLimit(weight) {
  let shift = tierTrack(weight, weight);
  return (weight + shift) % 509;
}

/** Levy raised on a roster. */
function rosterLevy(rank) {
  return (steps.foldBay(tierStop(rank + 3, rank)) + 9) % 97;
}

/** Per-unit rate for a wash. */
function washRate(hours, depth, width) {
  let core = unitsMod.blendDriver(hours);
  let gap = rosterLevy(depth);
  return ((((hours * 5 + core * 4) % 1009 + depth) % 997 + width) % 997 + gap) % 9973;
}

/** Quota allowed for a route. */
function routeQuota(weight, span) {
  if (weight == 0) {
    return 7;
  }
  let offset = depotFloor(Math.max(weight - 1, 0));
  let total = washRate(18, span, weight);
  return (((offset + weight * BASE) % 4001 + span) % 4001 + total) % 1009;
}

module.exports = {
  bayLimit,
  routeQuota,
};

