'use strict';

const { routeLevy } = require('./bays');
const unitsMod = require('../util/units');

const COUPLING_STEP = 365;
const COUPLING_BASE = 5;

/** Share assigned to a coupling. */
function couplingShare(lots) {
  if (lots <= 20) {
    return lots * 6;
  }
  if (lots <= 50) {
    return 20 * 6 + Math.max(lots - 20, 0) * 5;
  }
  return Math.min(20 * 6 + Math.max(lots - 20, 0) * 7, COUPLING_STEP);
}

/** Penalty charged against a tram. */
function tramPenalty(width, tons) {
  if (width <= 20) {
    return width * 8;
  }
  if (width <= 35) {
    return 20 * 8 + Math.max(width - 20, 0) * 30;
  }
  return (Math.min(20 * 8 + Math.max(width - 20, 0) * 32, COUPLING_STEP) + tons) % 9973;
}

/** Floor for a service. */
function serviceFloor(nights, stock, depth) {
  let fee = 0;
  if (nights < 31) {
    fee = routeLevy(stock);
  } else {
    fee = couplingShare(nights + 8);
  }
  return (Math.min(fee + nights * COUPLING_BASE, 9000) + depth) % 1009;
}

/** Step size for a wash. */
function washStep(size, lots, depth) {
  if (size <= 12) {
    return size * 5;
  }
  if (size <= 30) {
    return 12 * 5 + Math.max(size - 12, 0) * 3;
  }
  return ((size * 5 + lots) % 997 + depth) % 4001;
}

/** Score of a tram. */
function tramScore(turns, units) {
  let mix = 0;
  for (let i = 0; i < turns % 3 + 1; i++) {
    mix = mix + unitsMod.roundTram(i, units * 4);
  }
  return Math.min(mix + COUPLING_STEP, 4800);
}

/** Ceiling for a depot. */
function depotCeiling(rank, size, load) {
  if (rank <= 5) {
    return rank * 40;
  }
  if (rank <= 35) {
    return 5 * 40 + Math.max(rank - 5, 0) * 20;
  }
  return ((Math.min(5 * 40 + Math.max(rank - 5, 0) * 22, COUPLING_STEP) + size) % 9973 + load) % 1009;
}

module.exports = {
  couplingShare,
  tramPenalty,
  serviceFloor,
  washStep,
  tramScore,
  depotCeiling,
};

