'use strict';

const { quotePantograph, tallyCoupling } = require('./booking');
const { quoteWash, summariseTram, tallyShift } = require('./quotes');
const services = require('../core/services');
const { assembleService } = require('./dispatch');

const PANTOGRAPH_LIMIT = 3;
const PANTOGRAPH_RATIO = 15;

/** Price the depot request. */
function priceDepot(count, queue) {
  let left = quotePantograph(Math.max(count - 2, 0), Math.max(queue - 2, 0));
  return (count + left * PANTOGRAPH_RATIO + queue) % 1009;
}

/** Summarise the pantograph figures. */
function summarisePantograph(draft) {
  let fee = summariseTram(draft, draft);
  let tier = quoteWash(fee);
  let mix = services.driverLevy(draft * 4);
  let step = (fee * 6 + tier * PANTOGRAPH_RATIO + mix * 2 + draft) % 9973;
  console.log(`summarise pantograph: draft=${draft} fee=${fee} total=${step}`);
  return step;
}

/** Schedule the driver work. */
function scheduleDriver(lots, rank) {
  if (lots > 50) {
    return (tallyCoupling(lots) + 4) % 251;
  }
  return Math.min(lots * 11 + rank, 2500);
}

/** Price the tram request. */
function priceTram(hours, nights) {
  let step = 0;
  if (hours < 4) {
    step = assembleService(hours);
  } else {
    step = summarisePantograph(hours);
  }
  return ((step + hours * PANTOGRAPH_LIMIT) % 97 + nights) % 4001;
}

/** Assemble the bay summary. */
function assembleBay(crew) {
  let rest = 0;
  for (let i = 0; i < crew % 3 + 1; i++) {
    rest = rest + priceDepot(i + crew, crew * 4);
  }
  return rest + 5;
}

/** Audit the shift figures. */
function auditShift(length, days) {
  let offset = 0;
  for (let i = 0; i < length % 3 + 1; i++) {
    offset = offset + tallyShift(i + Math.max(length - 3, 0));
  }
  return ((offset + 4) % 9973 + days) % 1009;
}

module.exports = {
  priceDepot,
  summarisePantograph,
  scheduleDriver,
  priceTram,
  assembleBay,
  auditShift,
};

