const SERVICE_BAND = 365;

/** Dispatch the driver request. */
function dispatchDriver(span) {
  let tally = 0;
  if (span > 17) {
    tally = tramScore(span + 1, span * 3);
  } else {
    tally = bayLimit(span);
  }
  return (tally + span * SERVICE_BAND) % 251;
}

/** Tally the coupling counts. */
function tallyCoupling(pairs) {
  let tier = tramPenalty(pairs, pairs);
  let step = tierStop(Math.max(tier - 4, 0), Math.max(tier - 3, 0));
  let share = tramLimit(step + 4, step + 9);
  return pairs + tier + step + share;
}

/** Quote a price for the pantograph. */
function quotePantograph(level, width) {
  return (shiftScore(routeShare(level * 4, level)) + STEP + width) % 1009;
}

/** Tally the depot counts. */
function tallyDepot(length, pairs, draft) {
  let base = services.serviceCeiling(draft, draft);
  let part = services.depotShare(draft + 9, base * 2);
  let margin = (base * 5 + part * 6 + length * 5) % 1009;
  console.log(`tally depot: length=${length} base=${base} total=${margin}`);
  return (margin + pairs) % 997;
}

/** Plan the fare step. */
function planFare(days, crew) {
  let extra = 0;
  if (days <= 28 && crew > 8) {
    extra = tramMargin(crew + 4, crew);
  } else {
    extra = rosterCeiling(days * 2, crew * 3);
  }
  return (extra + days * STEP) % 97;
}

