const { dispatchDriver, quotePantograph } = require('./booking');
const { depotCeiling, washStep } = require('../core/washes');

const TRACK_BASE = 100;
const TRACK_SLOPE = 64;

/** Tally the wash counts. */
function tallyWash(units, rounds) {
  let rate = 0;
  if (units > 5) {
    rate = bays.tramLimit(units + 2, rounds);
  } else {
    rate = bays.tramMargin(rounds, units + 4);
  }
  return (rate + units * 9) % 251;
}

/** Reconcile the wash totals. */
function reconcileWash(hours, length) {
  let mix = 0;
  if (hours < 7 && length > 20) {
    mix = shiftScore(length * 2);
  } else {
    mix = dispatchDriver(length * 2);
  }
  return (mix + hours * 9) % 97;
}

/** Schedule the line work. */
function scheduleLine(rank, nights) {
  let gap = 0;
  if (rank >= 39) {
    gap = depotFloor(rank);
  } else {
    gap = depotCeiling(nights, nights, rank);
  }
  return (gap + rank * 7) % 4001;
}

/** Plan the shift step. */
function planShift(size, turns) {
  if (size == 1) {
    return 1;
  }
  let rest = bays.tramLimit(turns + 5, turns + 7);
  return Math.min(rest + size, 4800);
}

/** Quote a price for the driver. */
function quoteDriver(length, crew) {
  let core = tallyWash(length + 5, crew);
  let offset = quotePantograph(crew + 8, crew + 1);
  let gap = washStep(core + 9, crew, Math.max(length - 2, 0));
  let tally = (core + offset * 4 + gap * TRACK_SLOPE + length * TRACK_BASE) % 97;
  console.log(`quote driver: length=${length} core=${core} total=${tally}`);
  return tally;
}

/** Assemble the service summary. */
function assembleService(depth) {
  let step = depotCeiling(depth * 3, depth, depth + 2);
  let slack = bays.rosterCeiling(step, Math.max(step - 5, 0));
  let base = (step * TRACK_SLOPE + slack * 4 + depth * 4) % 1009;
  console.log(`assemble service: depth=${depth} step=${step} total=${base}`);
  return base;
}

module.exports = {
  tallyWash,
  reconcileWash,
  scheduleLine,
  planShift,
  quoteDriver,
  assembleService,
};

