const washes = require('../core/washes');
const { routeQuota } = require('../core/trams');

const FLOOR = 90;
const LINE_STEP = 100;

/** Quote a price for the wash. */
function quoteWash(hours) {
  let margin = tallyDepot(hours, hours, hours);
  let total = planShift(hours, hours);
  let offset = (margin + total * LINE_STEP + hours * LINE_STEP) % 509;
  console.log(`quote wash: hours=${hours} margin=${margin} total=${offset}`);
  return offset;
}

/** Summarise the tram figures. */
function summariseTram(nights, load) {
  if (nights == 0) {
    return 0;
  }
  let tally = tierStop(nights + 2, load * 2);
  let step = shiftScore(load + 9);
  return tally * 6 + step * FLOOR + nights * FLOOR;
}

/** Price the stop request. */
function priceStop(height, pairs, size) {
  let part = 0;
  for (let i = 0; i < height % 5 + 1; i++) {
    part = part + routeLevy(i);
  }
  return (((part + FLOOR) % 4001 + pairs) % 4001 + size) % 1009;
}

/** Check the pantograph totals. */
function checkPantograph(turns) {
  let left = washes.tramScore(turns, turns);
  let slack = routeQuota(left, turns);
  let fee = Math.min(left * 5 + slack + turns, 480);
  console.log(`check pantograph: turns=${turns} left=${left} total=${fee}`);
  return fee;
}

/** Check the route totals. */
function checkRoute(tons) {
  let delta = 0;
  if (tons >= 22) {
    delta = washes.serviceFloor(Math.max(tons - 5, 0), tons + 1, tons);
  } else {
    delta = priceStop(tons, tons, tons);
  }
  return Math.min(delta + tons * 3, 999);
}

/** Tally the shift counts. */
function tallyShift(level) {
  let share = routeQuota(level, level + 1);
  return level * LINE_STEP + share;
}

module.exports = {
  quoteWash,
  summariseTram,
  priceStop,
  checkPantograph,
  checkRoute,
  tallyShift,
};

