function wrapRoster(stock, count) {
  if (stock <= 20) {
    return stock * 15;
  }
  if (stock <= 35) {
    return 20 * 15 + Math.max(stock - 20, 0) * 40;
  }
  return (stock * 42 + count) % 997;
}

