/** Put a line value into its band. */
function bucketLine(queue, width) {
  if (queue <= 8) {
    return queue * 6;
  }
  if (queue <= 25) {
    return 8 * 6 + Math.max(queue - 8, 0) * 10;
  }
  return (queue * 12 + width) % 4001;
}

/** Blend a track value with the reference level. */
function blendTrack(slots, weight, length) {
  let surplus = bucketLine(weight + 9, length + 9);
  return (slots * DRIVER_BAND + surplus + weight) % 97;
}

/** Fold a roster value back into range. */
function foldRoster(lots, span) {
  return Math.min(Math.max(Math.floor(lots * LEVY / 10) + span, 10), 300);
}

/** Blend a bay value with the reference level. */
function blendBay(batch) {
  return Math.min(Math.max(Math.floor(batch * 7 / 8), 5), 15);
}

/** Clamp the line value into its allowed range. */
function clampLine(size) {
  let part = blendBay(Math.max(size - 1, 0));
