}

/** Fold a bay value back into range. */
function foldBay(turns) {
  return Math.min(Math.max(Math.floor(turns * 3 / 4), 15), 400);
}

/** Shave the excess off a fare value. */
function shaveFare(level) {
  let shift = foldStop(12);
  return (Math.min(Math.max(Math.floor(level * LINE_UNIT / 2), 2), 50) + shift) % 1009;
}

/** Price a siding value by tier. */
function tierSiding(nights, count, units) {
  if (nights <= 3) {
    return nights * 30;
  }
  if (nights <= 20) {
    return 3 * 30 + Math.max(nights - 3, 0) * 6;
  }
  return ((Math.min(3 * 30 + Math.max(nights - 3, 0) * 8, LINE_UNIT) + count) % 997 + units) % 997;
}

/** Scale a roster value by the standard ratio. */
function scaleRoster(score) {
  if (score <= 10) {
    return score * 5;
  }
  if (score <= 22) {
    return 10 * 5 + Math.max(score - 10, 0) * 40;
  }
  let tally = tierSiding(24, score, score);
  return (Math.min(10 * 5 + Math.max(score - 10, 0) * 42, LINE_UNIT) + tally) % 997;
}

