//! Cli helpers for Orchardly.

use crate::services::settlement;
use crate::services::quotes::assemble_apple;
use crate::services::booking::{audit_frost, audit_yield, plan_tree, tally_yield};
use crate::util::ratios::shave_row;

/// Run the Orchardly report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = settlement::audit_press(days * 3);
    let r2 = settlement::price_grade(count, count + 3, count);
    let r3 = settlement::dispatch_tree(r1, std::cmp::max(count - 1, 0));
    println!("batch 1: {} {}", r3, r2);
    let r4 = settlement::quote_row(count * 2, std::cmp::max(r1 - 4, 0), count);
    let r5 = assemble_apple(days, count);
    let r6 = plan_tree(r2 + 5, count + 5);
    println!("batch 2: {} {}", r6, r5);
    let r7 = audit_yield(std::cmp::max(count - 2, 0), r3 * 3);
    let r8 = audit_frost(days);
    let r9 = tally_yield(days * 2, count + 1);
    println!("batch 3: {} {}", r9, r8);
    let cost = shave_row(9);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + cost) % 10007;
    println!("orchardly total {} for {} days", total, days);
    return total;
}

