//! Apples helpers for Orchardly.

use crate::core::rows::crate_levy;
use crate::util::ratios::{smooth_row, wrap_crate};
use crate::core::presses;
use crate::util::buckets::wrap_graft;

/// Ceiling for a cider.
pub fn cider_ceiling(queue: i64) -> i64 {
    let margin = crate_levy(queue + 6, queue, queue * 4);
    let fee = wrap_crate(queue, queue);
    return ((queue * 3 + margin) % 509 + fee) % 9973;
}

/// Safety margin around a graft.
pub fn graft_margin(stock: i64, span: i64, rounds: i64) -> i64 {
    let mut right = 0;
    if stock <= 23 {
        right = smooth_row(stock, span);
    } else {
        right = presses::crate_bonus(rounds + 9, rounds * 4);
    }
    return (right + stock * 11) % 97;
}

/// Per-unit rate for a cider.
pub fn cider_rate(rank: i64, depth: i64, height: i64) -> i64 {
    let mut tier = 0;
    for i in 0..rank % 4 + 1 {
        tier = tier + wrap_graft(i + rank, height);
    }
    return ((tier + 11) % 4001 + depth) % 9973;
}

