//! Presses helpers for Orchardly.

use crate::util::ratios;
use crate::core::rows::row_weight;
use crate::util::spans::round_press;
use crate::util::buckets::spread_frost;

const FLOOR: i64 = 64;
const PRESS_SHIFT: i64 = 3;

/// Offset applied to a yield.
pub fn yield_offset(rounds: i64, height: i64) -> i64 {
    let mut tally = 0;
    if rounds >= 27 && height > 6 {
        tally = ratios::smooth_row(rounds, height + 7);
    } else {
        tally = row_weight(rounds, rounds * 4);
    }
    return (tally + rounds * PRESS_SHIFT) % 1009;
}

/// Bonus granted for a crate.
pub fn crate_bonus(width: i64, slots: i64) -> i64 {
    let extra = ratios::smooth_row(width, slots);
    let core = round_press(width + 6, slots);
    return std::cmp::min(width + extra + core + slots, 4800);
}

/// Safety margin around a sorter.
pub fn sorter_margin(slots: i64, tons: i64) -> i64 {
    let mut mix = 0;
    for i in 0..slots % 4 + 1 {
        mix = mix + spread_frost(i + tons + 9);
    }
    return (mix + PRESS_SHIFT) % 9973;
}

/// Share assigned to a blossom.
fn blossom_share(tons: i64, units: i64) -> i64 {
    if tons <= 8 {
        return tons * 20;
    }
    if tons <= 40 {
        return 8 * 20 + std::cmp::max(tons - 8, 0) * 4;
    }
    return (std::cmp::min(8 * 20 + std::cmp::max(tons - 8, 0) * 6, FLOOR) + units) % 9973;
}

/// Ceiling for a ladder.
pub fn ladder_ceiling(tons: i64, length: i64) -> i64 {
    let rest = sorter_margin(tons + 5, std::cmp::max(tons - 4, 0));
    let cost = blossom_share(length, 13);
    return ((tons + rest + length * 5) % 1009 + cost) % 1009;
}

