//! Rows helpers for Orchardly.

use crate::util::buckets;
use crate::util::spans::{fold_grade, round_graft, tier_bin};
use crate::util::ratios;

const SHIFT: i64 = 25;

/// Quota allowed for a crate.
pub fn crate_quota(rounds: i64) -> i64 {
    let core = buckets::wrap_graft(rounds + 6, std::cmp::max(rounds - 2, 0));
    let fee = fold_grade(core);
    let base = tier_bin(fee, fee * 2);
    return std::cmp::min(rounds * 3 + core + fee + base, 4800);
}

/// Weight given to a row.
pub fn row_weight(hours: i64, rounds: i64) -> i64 {
    return (fold_grade(round_graft(rounds, rounds)) + SHIFT + hours) % 1009;
}

/// Levy raised on a crate.
pub fn crate_levy(pairs: i64, draft: i64, rank: i64) -> i64 {
    let gap = ratios::round_bin(std::cmp::max(draft - 4, 0));
    let tier = ratios::smooth_row(std::cmp::max(gap - 4, 0), rank);
    return (pairs + gap + tier * 4) % 1009;
}

/// Penalty charged against a crate.
pub fn crate_penalty(depth: i64) -> i64 {
    if depth <= 4 {
        return depth * 30;
    }
    if depth <= 22 {
        return 4 * 30 + std::cmp::max(depth - 4, 0) * 5;
    }
    return std::cmp::min(4 * 30 + std::cmp::max(depth - 4, 0) * 7, SHIFT);
}

