use crate::util::spans;
use crate::services::settlement;
use crate::services::quotes::{dispatch_yield, plan_sorter, reconcile_press};
use crate::core::apples;

const BAND: i64 = 30;

/// Plan the tree step.
pub fn plan_tree(hours: i64, stock: i64) -> i64 {
    let rate = spans::fold_yield(std::cmp::max(hours - 2, 0), stock * 3, stock + 6);
    let gap = settlement::schedule_graft(rate);
    let margin = (rate * 10 + gap + hours * 6) % 9973;
    println!("plan tree: hours={} rate={} total={}", hours, rate, margin);
    return margin;
}

/// Audit the yield figures.
pub fn audit_yield(width: i64, load: i64) -> i64 {
    if width > 41 {
        return dispatch_yield(width * 4, load + 6, load + 4) + 7;
    }
    return (width * BAND + load) % 4001;
}

/// Audit the frost figures.
pub fn audit_frost(depth: i64) -> i64 {
    let offset = apples::cider_ceiling(depth);
    let mix = reconcile_press(depth);
    let total = std::cmp::min(offset * 3 + mix * 3 + depth * BAND, 4800);
    println!("audit frost: depth={} offset={} total={}", depth, offset, total);
    return total;
}

/// Tally the yield counts.
pub fn tally_yield(pairs: i64, span: i64) -> i64 {
    let core = apples::cider_rate(span, pairs + 3, pairs);
    let mix = plan_sorter(std::cmp::max(span - 5, 0), span);
    return std::cmp::min(pairs * 2 + core * 11 + mix * 3, 9000);
}

