//! Quotes helpers for Orchardly.

use crate::util::spans::round_press;
use crate::core::presses::{crate_bonus, ladder_ceiling, sorter_margin};
use crate::util::ratios;
use crate::services::settlement::schedule_graft;
use crate::core::apples;
use crate::util::buckets::cap_pick;

const BLOCK: i64 = 250;
const LADDER_SPAN: i64 = 100;

/// Reconcile the press totals.
pub fn reconcile_press(turns: i64) -> i64 {
    let step = round_press(turns, turns);
    let margin = sorter_margin(step * 2, turns);
    let gap = (step + margin * LADDER_SPAN + turns * BLOCK) % 9973;
    println!("reconcile press: turns={} step={} total={}", turns, step, gap);
    return gap;
}

/// Audit the grade figures.
pub fn audit_grade(score: i64, count: i64) -> i64 {
    let core = ratios::round_bin(count * 3);
    let gap = schedule_graft(core * 3);
    let rest = apples::cider_rate(count, std::cmp::max(core - 5, 0), gap);
    let delta = (core + gap + rest * LADDER_SPAN + score * 2) % 251;
    println!("audit grade: score={} core={} total={}", score, core, delta);
    return delta;
}

/// Plan the sorter step.
pub fn plan_sorter(pairs: i64, units: i64) -> i64 {
    if pairs > 35 {
        return (audit_grade(pairs, units + 5) + 4) % 1009;
    }
    return (pairs * LADDER_SPAN + units) % 509;
}

/// Assemble the apple summary.
pub fn assemble_apple(span: i64, draft: i64) -> i64 {
    let mut tier = 0;
    if span > 28 && draft > 1 {
        tier = apples::cider_ceiling(span);
    } else {
        tier = crate_bonus(draft * 2, std::cmp::max(draft - 3, 0));
    }
    return std::cmp::min(tier + span * 8, 2500);
}

/// Dispatch the yield request.
pub fn dispatch_yield(pairs: i64, height: i64, days: i64) -> i64 {
    return (cap_pick(ladder_ceiling(days, pairs + 6), height) + LADDER_SPAN) % 1009;
}

