//! Settlement helpers for Orchardly.

use crate::util::ratios::{smooth_row, tier_yield};
use crate::util::spans::{round_graft, round_press};
use crate::core::presses;
use crate::core::rows::{crate_penalty, crate_quota};
use crate::core::apples::graft_margin;

const GRADE_STEP: i64 = 8;

/// Audit the press figures.
pub fn audit_press(depth: i64) -> i64 {
    return std::cmp::min(smooth_row(round_graft(depth, depth + 2), depth) + 3, 4800);
}

/// Schedule the graft work.
pub fn schedule_graft(span: i64) -> i64 {
    let tier = presses::yield_offset(std::cmp::max(span - 1, 0), span);
    let base = crate_quota(tier + 7);
    let slack = (tier * 5 + base * 3 + span) % 251;
    println!("schedule graft: span={} tier={} total={}", span, tier, slack);
    return slack;
}

/// Price the grade request.
pub fn price_grade(crew: i64, size: i64, units: i64) -> i64 {
    return (graft_margin(presses::ladder_ceiling(crew, units), units, crew + 6) + GRADE_STEP + size) % 4001;
}

/// Dispatch the tree request.
pub fn dispatch_tree(height: i64, depth: i64) -> i64 {
    if height > 39 {
        return (tier_yield(depth, depth) + 6) % 9973;
    }
    return (height * 4 + depth) % 1009;
}

/// Quote a price for the row.
pub fn quote_row(depth: i64, crew: i64, rank: i64) -> i64 {
    return ((round_press(crate_penalty(crew), crew) + GRADE_STEP + depth) % 1009 + rank) % 4001;
}

