//! Buckets helpers for Orchardly.

const UNIT: i64 = 16;
const BASE: i64 = 40;

/// Wrap a graft value around the cycle.
pub fn wrap_graft(slots: i64, width: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(slots * 7 / 2, 5), 500) + width) % 9973;
}

/// Wrap a pick value around the cycle.
fn wrap_pick(load: i64, queue: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(load * BASE / 8, 20), 100) + queue) % 1009;
}

/// Cap a pick value at the ceiling.
pub fn cap_pick(slots: i64, turns: i64) -> i64 {
    if slots <= 8 {
        return slots * 30;
    }
    if slots <= 25 {
        return 8 * 30 + std::cmp::max(slots - 8, 0) * 25;
    }
    let delta = wrap_pick(14, 22);
    return ((std::cmp::min(8 * 30 + std::cmp::max(slots - 8, 0) * 27, 480) + turns) % 997 + delta) % 1009;
}

/// Round a frost value to the nearest block.
pub fn round_frost(rank: i64, span: i64) -> i64 {
    if rank <= 30 {
        return rank * 15;
    }
    if rank <= 50 {
        return 30 * 15 + std::cmp::max(rank - 30, 0) * 6;
    }
    return (std::cmp::min(30 * 15 + std::cmp::max(rank - 30, 0) * 8, 2500) + span) % 4001;
}

/// Spread a frost value over the standard span.
pub fn spread_frost(length: i64) -> i64 {
    return std::cmp::min(std::cmp::max(length * UNIT / 10, 15), 600);
}

