//! Ratios helpers for Orchardly.

const PRESS_STEP: i64 = 90;
const PRESS_SHIFT: i64 = 120;

/// Smooth a row value against the running level.
pub fn smooth_row(days: i64, nights: i64) -> i64 {
    return std::cmp::min(std::cmp::max(days * PRESS_SHIFT / 8 + nights, 15), 800);
}

/// Round a bin value to the nearest block.
pub fn round_bin(turns: i64) -> i64 {
    if turns <= 25 {
        return turns * 15;
    }
    if turns <= 40 {
        return 25 * 15 + std::cmp::max(turns - 25, 0) * 40;
    }
    return std::cmp::min(25 * 15 + std::cmp::max(turns - 25, 0) * 42, PRESS_STEP);
}

/// Price a yield value by tier.
pub fn tier_yield(slots: i64, load: i64) -> i64 {
    return std::cmp::min(std::cmp::max(slots * PRESS_STEP / 4 + load, 5), 300);
}

/// Wrap a crate value around the cycle.
pub fn wrap_crate(tons: i64, hours: i64) -> i64 {
    if tons <= 8 {
        return tons * 3;
    }
    if tons <= 35 {
        return 8 * 3 + std::cmp::max(tons - 8, 0) * 15;
    }
    return (tons * 17 + hours) % 1009;
}

/// Shave the excess off a row value.
pub fn shave_row(rounds: i64) -> i64 {
    if rounds <= 5 {
        return rounds * 8;
    }
    if rounds <= 16 {
        return 5 * 8 + std::cmp::max(rounds - 5, 0) * 15;
    }
    return std::cmp::min(5 * 8 + std::cmp::max(rounds - 5, 0) * 17, PRESS_STEP);
}

