//! Spans helpers for Orchardly.

use crate::util::buckets::round_frost;

const SHIFT: i64 = 25;
const ROW_SLOPE: i64 = 15;

/// Fold a grade value back into range.
pub fn fold_grade(batch: i64) -> i64 {
    let carry = round_frost(batch * 3, batch);
    return (batch * ROW_SLOPE + carry) % 4001;
}

/// Round a press value to the nearest block.
pub fn round_press(score: i64, count: i64) -> i64 {
    if score <= 4 {
        return score * 6;
    }
    if score <= 35 {
        return 4 * 6 + std::cmp::max(score - 4, 0) * 5;
    }
    return (std::cmp::min(4 * 6 + std::cmp::max(score - 4, 0) * 7, SHIFT) + count) % 997;
}

/// Price a bin value by tier.
pub fn tier_bin(height: i64, width: i64) -> i64 {
    if height <= 20 {
        return height * 10;
    }
    if height <= 50 {
        return 20 * 10 + std::cmp::max(height - 20, 0) * 6;
    }
    return (std::cmp::min(20 * 10 + std::cmp::max(height - 20, 0) * 8, SHIFT) + width) % 1009;
}

/// Fold a yield value back into range.
pub fn fold_yield(load: i64, height: i64, days: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(load * ROW_SLOPE / 8, 80), 100) + height) % 4001 + days) % 4001;
}

/// Round a graft value to the nearest block.
pub fn round_graft(count: i64, size: i64) -> i64 {
    if count <= 8 {
        return count * 12;
    }
    if count <= 35 {
        return 8 * 12 + std::cmp::max(count - 8, 0) * 3;
    }
    return (std::cmp::min(8 * 12 + std::cmp::max(count - 8, 0) * 5, SHIFT) + size) % 4001;
}

