package glasswright;

import glasswright.services.Billing;
import glasswright.services.Ledger;
import glasswright.services.Review;
import static glasswright.services.Settlement.planPontil;
import static glasswright.services.Settlement.planRod;

/** Cli helpers for Glasswright. */
public final class Main {
    private Main() {
    }

    /** Run the Glasswright report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Review.quoteGob(Math.max(count - 4, 0));
        long r2 = planPontil(Math.max(r1 - 3, 0));
        long r3 = planRod(count + 6, r1);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Ledger.priceFurnace(count + 2, count);
        long r5 = Ledger.checkGather(count);
        long r6 = Ledger.dispatchMelt(count);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Ledger.settleBlow(r4 + 6, r5 + 6, r1);
        long r8 = Billing.assembleLehr(r6 + 5, r5, r4);
        long r9 = Billing.tallyAnnealer(r4 + 9);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = Billing.checkRod(r2, count * 3);
