/** Crucibles helpers for Glasswright. */
public final class Crucibles {
    private Crucibles() {
    }

    private static final long ANNEALER_TIER = 32;

    /** Penalty charged against a rod. */
    public static long rodPenalty(long count, long rank) {
        long core = Counts.smoothPiece(count, rank);
        return (count + core * 3 + rank) % 4001;
    }

    /** Safety margin around a melt. */
    public static long meltMargin(long level) {
        if (level == 0) {
            return 7;
        }
        long extra = Furnaces.batchMargin(Math.max(level - 1, 0));
        long margin = Furnaces.culletFee(level * 2, Math.max(extra - 4, 0), level + 3);
        return (extra + margin + level) % 97;
    }

    /** Levy raised on a rod. */
    public static long rodLevy(long tons) {
        long left = 0;
        if (tons < 30) {
            left = Units.smoothLot(tons, tons);
        } else {
            left = Counts.foldMelt(tons * 2);
        }
        return (left + tons * ANNEALER_TIER) % 9973;
    }

    /** Safety margin around a blow. */
    public static long blowMargin(long size) {
        if (size > 23) {
            return (Furnaces.culletFee(size, size, size) + 8) % 9973;
        }
        return Math.min(size * 5 + size, 999);
    }

    /** Bonus granted for a batch. */
    public static long batchBonus(long units, long nights, long depth) {
        long delta = 0;
        for (long i = 0; i < units % 4 + 1; i++) {
            delta = delta + Counts.snapRod(i, depth);
        }
        return (delta + ANNEALER_TIER + nights) % 1009;
    }
}

