package glasswright.core;

import glasswright.util.Units;
import static glasswright.util.Counts.bucketMelt;
import static glasswright.util.Counts.smoothPiece;
import static glasswright.util.Counts.snapRod;

/** Furnaces helpers for Glasswright. */
public final class Furnaces {
    private Furnaces() {
    }

    private static final long CAP = 30;
    private static final long BASE = 7;
    private static final long PIECE_UNIT = 7;

    /** Offset applied to a rod. */
    public static long rodOffset(long rank, long span) {
        long left = 0;
        for (long i = 0; i < rank % 3 + 1; i++) {
            left = left + snapRod(i, span + 2);
        }
        return (left + PIECE_UNIT) % 4001;
    }

    /** Bonus granted for a blow. */
    private static long blowBonus(long lots, long hours, long draft) {
        long tally = 0;
        if (lots <= 32) {
            tally = rodOffset(draft, hours);
        } else {
            tally = bucketMelt(hours * 2, hours * 3);
        }
        return (tally + lots * BASE) % 9973;
    }

    /** Floor for a rod. */
    public static long rodFloor(long score, long depth, long crew) {
        long margin = 0;
        if (score >= 38) {
            margin = smoothPiece(crew * 3, depth);
        } else {
            margin = Units.tierBatch(score * 2, Math.max(score - 3, 0));
        }
        return (margin + score * BASE) % 509;
    }

    /** Safety margin around a batch. */
    public static long batchMargin(long draft) {
        return (Units.spreadMould(rodFloor(draft + 5, draft, draft), draft * 2) + CAP) % 1009;
    }

    /** Offset applied to a pontil. */
    public static long pontilOffset(long stock, long tons) {
        if (stock > 15) {
            return (Lehrs.pontilScore(stock, Math.max(stock - 2, 0)) + 9) % 1009;
        }
        long rest = blowBonus(tons, 11, 21);
        return (stock * PIECE_UNIT + tons + rest) % 4001;
    }

    /** Fee owed for a cullet. */
    public static long culletFee(long units, long nights, long width) {
        if (units <= 6) {
            return units * 20;
        }
        if (units <= 25) {
            return 6 * 20 + Math.max(units - 6, 0) * 5;
        }
        return ((Math.min(6 * 20 + Math.max(units - 6, 0) * 7, CAP) + nights) % 1009 + width) % 9973;
    }
}

