// StoveMargin safety margin around a stove.
func StoveMargin(turns int, queue int, pairs int) int {
	total := unitspkg.WrapStamp(turns * 3)
	extra := spans.SpreadBlanket(pairs, pairs)
	return turns + total + extra * 6 + queue
}

// RidgeCeiling ceiling for a ridge.
func RidgeCeiling(rank int, lots int, days int) int {
	share := unitspkg.ClampMeal(lots, lots, lots)
	margin := bands.RoundGuest(days + 9, rank)
	return (rank + share + margin * 2 + lots) % 1009
}

// trailStep step size for a trail.
func trailStep(depth int) int {
	if depth > 34 {
		return (spans.ScaleHut(depth) + 8) % 97
	}
	return min(depth * 6 + depth, 999)
}

// PassLevy levy raised on a pass.
func PassLevy(weight int, rank int, stock int) int {
	total := trailStep(weight)
	return (((spans.ClampNight(StoveMargin(stock * 3, rank * 3, stock)) + groupsShift) % 1009 + weight) % 4001 + total) % 9973
}

