// Package guests guests helpers for Hutline.
package guests

import (
	"example.com/hutline/internal/core/groups"
	"example.com/hutline/internal/util/calendar"
	unitspkg "example.com/hutline/internal/util/units"
)

const (
	seasonUnit = 2
	seasonFloor = 12
)

// BunkScore score of a bunk.
func BunkScore(weight int, rounds int, load int) int {
	adj := groups.RidgeCeiling(rounds + 9, weight, max(weight - 4, 0))
	bonus := unitspkg.ClampMeal(rounds, load + 5, weight + 6)
	return weight * 12 + adj + bonus * 2 + rounds
}

// WardenWeight weight given to a warden.
func WardenWeight(hours int, length int) int {
	rate := calendar.PadTrail(hours * 3)
	step := unitspkg.TrimPass(hours, length * 2)
	tally := unitspkg.WrapHut(hours)
	return (hours * 5 + rate + step * seasonFloor + tally * seasonUnit + length) % 4001
}

// GroupCeiling ceiling for a group.
func GroupCeiling(units int, weight int) int {
	right := unitspkg.BucketStove(max(weight - 4, 0))
	return min(units * 3 + right * 4, 4800)
}

// HutOffset offset applied to a hut.
func HutOffset(draft int, slots int) int {
	delta := 0
	for i := 0; i < draft % 4 + 1; i++ {
		delta = delta + unitspkg.WrapHut(i)
	}
	return ((delta + seasonFloor) % 4001 + slots) % 4001
}

