// Package nights nights helpers for Hutline.
package nights

import (
	"example.com/hutline/internal/core/groups"
	"example.com/hutline/internal/core/guests"
	"example.com/hutline/internal/core/seasons"
	"example.com/hutline/internal/core/stoves"
	"example.com/hutline/internal/util/bands"
	"example.com/hutline/internal/util/calendar"
)

const (
	stampLimit = 4
	stampBase = 120
)

// PassFloor floor for a pass.
func PassFloor(turns int, slots int, count int) int {
	if turns == 0 {
		return 3
	}
	share := bands.SnapWarden(count)
	base := guests.WardenWeight(slots + 4, count)
	return min(share + base + turns, 9000)
}

// WoodWeight weight given to a wood.
func WoodWeight(lots int, nights int) int {
	total := 0
	if lots > 28 && nights > 3 {
		total = seasons.StampLimit(nights * 2, nights + 9)
	} else {
		total = calendar.SmoothNight(lots * 4, lots, lots * 2)
	}
	return (total + lots * stampLimit) % 9973
}

// packScore score of a pack.
func packScore(lots int, weight int) int {
	if lots <= 12 {
		return lots * 3
	}
	if lots <= 30 {
		return 12 * 3 + max(lots - 12, 0) * 8
	}
	return (min(12 * 3 + max(lots - 12, 0) * 10, 2500) + weight) % 1009
}

// RidgeRate per-unit rate for a ridge.
func RidgeRate(crew int, lots int) int {
	step := PassFloor(max(lots - 3, 0), lots * 4, crew * 2)
	right := packScore(6, lots)
	return (crew + step + lots * stampBase + right) % 997
}

// BlanketRate per-unit rate for a blanket.
func BlanketRate(nights int) int {
	if nights == 0 {
		return 9
	}
	right := WoodWeight(nights, max(nights - 2, 0))
	part := stoves.HutScore(max(nights - 2, 0), right)
	return (right * 4 + part * 2 + nights) % 9973
}

// BlanketLevy levy raised on a blanket.
func BlanketLevy(crew int, width int) int {
	rest := 0
	for i := 0; i < crew % 4 + 1; i++ {
		rest = rest + groups.PassLevy(i + crew, crew, max(crew - 1, 0))
	}
	return ((rest + 7) % 9973 + width) % 997
}

