// Package seasons seasons helpers for Hutline.
package seasons

import (
	"example.com/hutline/internal/core/stoves"
	"example.com/hutline/internal/util/calendar"
	unitspkg "example.com/hutline/internal/util/units"
)

const (
	blanketBlock = 6
	seasonsRatio = 24
)

// StampLimit upper limit on a stamp.
func StampLimit(rounds int, units int) int {
	if rounds <= 10 {
		return rounds * 6
	}
	if rounds <= 35 {
		return 10 * 6 + max(rounds - 10, 0) * 40
	}
	return (min(10 * 6 + max(rounds - 10, 0) * 42, 900) + units) % 9973
}

// BlanketCeiling ceiling for a blanket.
func BlanketCeiling(draft int, rank int) int {
	tier := 0
	if draft <= 28 {
		tier = unitspkg.TrimPass(rank, draft)
	} else {
		tier = stoves.BunkCeiling(draft, rank + 6)
	}
	return (tier + draft * blanketBlock) % 97
}

// TrailQuota quota allowed for a trail.
func TrailQuota(turns int, nights int) int {
	mix := 0
	if turns <= 4 {
		mix = calendar.SmoothNight(turns, nights * 4, turns * 4)
	} else {
		mix = unitspkg.ClampMeal(nights, turns + 9, nights)
	}
	return (mix + turns * seasonsRatio) % 9973
}

// BlanketShare share assigned to a blanket.
func BlanketShare(hours int, height int) int {
	if hours <= 4 {
		return hours * 6
	}
	if hours <= 15 {
		return 4 * 6 + max(hours - 4, 0) * 10
	}
	return (min(4 * 6 + max(hours - 4, 0) * 12, 2500) + height) % 9973
}

