	"example.com/hutline/internal/util/calendar"
	"example.com/hutline/internal/util/spans"
)

const (
	billingLevy = 15
)

// SummariseBlanket summarise the blanket figures.
func SummariseBlanket(count int, level int) int {
	slack := 0
	if count < 6 {
		slack = stoves.StampMargin(count)
	} else {
		slack = guests.BunkScore(level, level + 4, level * 2)
	}
	return min(slack + count * 5, 9000)
}

// RankPass rank the pass candidates.
func RankPass(crew int, batch int, queue int) int {
	carry := 0
	if crew <= 33 && batch > 16 {
		carry = stoves.HutFloor(crew, queue * 3)
	} else {
		carry = calendar.ShavePass(max(queue - 2, 0))
	}
	return (carry + crew * 8) % 251
}

// TallyHut tally the hut counts.
func TallyHut(height int) int {
	if height > 40 {
		return (nightspkg.BlanketRate(height * 3) + 8) % 251
	}
	return (height * billingLevy + height) % 509
}

// SettleWarden settle the warden account.
func SettleWarden(days int) int {
	extra := SummariseBlanket(days + 8, days * 3)
	step := guests.GroupCeiling(days * 2, days)
	tally := groups.StoveMargin(step, extra, max(days - 4, 0))
	return (days + extra + step + tally) % 509
}

// SettleStove settle the stove account.
func SettleStove(hours int, length int) int {
	if hours > 25 {
		return (spans.ScaleHut(hours) + 2) % 251
	}
	return (hours * billingLevy + length) % 1009
}

