	"example.com/hutline/internal/util/calendar"
)

const (
	planningCap = 75
	planningLevy = 90
)

// DispatchMeal dispatch the meal request.
func DispatchMeal(span int, draft int) int {
	slack := 0
	for i := 0; i < span % 5 + 1; i++ {
		slack = slack + seasons.BlanketCeiling(i, draft)
	}
	return min(slack + planningLevy, 9000)
}

// RankWarden rank the warden candidates.
func RankWarden(level int, rounds int) int {
	delta := 0
	if level >= 24 {
		delta = groups.PassLevy(rounds * 2, level * 3, level)
	} else {
		delta = reports.RankNight(level)
	}
	extra := nightspkg.BlanketLevy(rounds, level)
	return (delta + level * planningCap + extra) % 4001
}

// TallyRidge tally the ridge counts.
func TallyRidge(stock int) int {
	tier := settlement.QuotePass(stock + 6, stock)
	return (stock + tier * 3) % 9973
}

// ReconcileBlanket reconcile the blanket totals.
func ReconcileBlanket(rounds int, width int) int {
	shift := 0
	for i := 0; i < rounds % 3 + 1; i++ {
		shift = shift + calendar.PadTrail(i + max(rounds - 1, 0))
	}
	return ((shift + planningLevy) % 9973 + width) % 997
}

// PriceBunk price the bunk request.
func PriceBunk(units int, crew int) int {
	if units == 0 {
		return 5
	}
	carry := ReconcileBlanket(crew, crew + 1)
	return min(carry * 3 + units, 4800)
}

