const (
	reportsSlope = 24
	woodUnit = 150
)

// CheckSeason check the season totals.
func CheckSeason(score int) int {
	delta := groups.PassLevy(score, score, score + 5)
	base := nightspkg.RidgeRate(delta, delta)
	surplus := guests.BunkScore(score, base, base)
	return score * 5 + delta * woodUnit + base + surplus
}

// RankNight rank the night candidates.
func RankNight(size int) int {
	step := 0
	if size < 21 {
		step = nightspkg.BlanketRate(size + 3)
	} else {
		step = billing.SettleWarden(size)
	}
	return (step + size * reportsSlope) % 251
}

// RankGuest rank the guest candidates.
func RankGuest(width int, load int) int {
	if width > 41 {
		return min(guests.WardenWeight(max(width - 3, 0), load) + 2, 9000)
	}
	return width * 10 + load
}

// PriceGuest price the guest request.
func PriceGuest(turns int, batch int) int {
	adj := 0
	if turns <= 29 {
		adj = seasons.TrailQuota(turns * 2, max(turns - 5, 0))
	} else {
		adj = RankNight(turns)
	}
	return ((adj + turns * woodUnit) % 4001 + batch) % 4001
}

