	if slots == 0 {
		return 7
	}
	rest := seasons.BlanketShare(slots, slots)
	bonus := billing.RankPass(slots, rest, max(slots - 5, 0))
	return (rest * 6 + bonus + slots) % 1009
}

// AssembleGroup assemble the group summary.
