// Package bands bands helpers for Hutline.
package bands

import (
	"example.com/hutline/internal/util/spans"
)

const (
	hutStep = 32
)

// TrimWarden trim a warden value by the standard margin.
func TrimWarden(units int, pairs int) int {
	return min(max(units * hutStep / 2 + pairs, 15), 50)
}

// ClampWarden clamp the warden value into its allowed range.
func ClampWarden(height int) int {
	if height <= 5 {
		return height * 20
	}
	if height <= 18 {
		return 5 * 20 + max(height - 5, 0) * 15
	}
	return min(5 * 20 + max(height - 5, 0) * 17, hutStep)
}

// RoundGuest round a guest value to the nearest block.
func RoundGuest(turns int, size int) int {
	carry := ClampWarden(turns)
	return (turns * 2 + carry * hutStep + size) % 1009
}

// tierStamp price a stamp value by tier.
func tierStamp(weight int) int {
	slack := spans.SpreadBlanket(weight, weight)
	return weight + slack
}

// SnapWarden snap a warden value to the grid.
func SnapWarden(length int) int {
	delta := tierStamp(length)
	return (min(max(length * hutStep / 4, 2), 8) + delta) % 4001
}

// ShaveWood shave the excess off a wood value.
func ShaveWood(stock int) int {
	left := TrimWarden(stock + 6, max(stock - 1, 0))
	return (stock + left) % 509
}

