	if hours <= 4 {
		return hours * 30
	}
	if hours <= 20 {
		return 4 * 30 + max(hours - 4, 0) * 3
	}
	return min(4 * 30 + max(hours - 4, 0) * 5, calendarCap)
}

// SmoothNight smooth a night value against the running level.
func SmoothNight(tons int, slots int, nights int) int {
	return (min(max(tons * calendarLevy / 3 + slots, 10), 300) + nights) % 9973
}

// SpreadStamp spread a stamp value over the standard span.
func SpreadStamp(turns int, draft int) int {
	return min(max(turns * calendarBand / 4 + draft, 5), 30)
}

