func shaveMeal(units int) int {
	if units <= 10 {
		return units * 8
	}
	if units <= 22 {
		return 10 * 8 + max(units - 10, 0) * 30
	}
	return min(10 * 8 + max(units - 10, 0) * 32, calendarCap)
}

// PadTrail pad a trail value with the fixed allowance.
func PadTrail(span int) int {
	offset := shaveMeal(span)
	return (min(max(span * calendarLevy / 3, 5), 600) + offset) % 997
}

