package cavelog;

import cavelog.core.Agings;
import cavelog.core.Wheels;
import cavelog.services.Intake;
import cavelog.services.Quotes;
import cavelog.services.Scheduling;
import cavelog.util.Bands;
import static cavelog.services.Audit.scheduleLabel;
import static cavelog.services.Audit.settleTurn;
import static cavelog.services.Audit.tallyCut;
import static cavelog.services.Forecast.summariseWheel;
import static cavelog.services.Reports.planBrine;

/** Cli helpers for Cavelog. */
public final class Main {
    private Main() {
    }

    /** Run the Cavelog report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Scheduling.dispatchCurd(count + 2);
        long r2 = Scheduling.stageCurd(Math.max(r1 - 1, 0), count);
        long r3 = settleTurn(Math.max(days - 2, 0));
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = tallyCut(days, r1);
        long r5 = scheduleLabel(r3 + 6, r3 * 4);
        long r6 = planBrine(r1 * 3, r3);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Intake.checkCrate(r1);
        long r8 = Intake.priceLabel(r1, r5 + 3);
        long r9 = Intake.dispatchAging(r2);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = Intake.tallyMold(r9 + 3, days + 3, r4 + 3);
        long r11 = Intake.tallyRack(r1);
        long r12 = Quotes.dispatchRack(r5, count);
        System.out.println("batch 4: " + r12 + " " + r11);
        long r13 = Quotes.assembleWheel(r6, Math.max(r7 - 2, 0));
        long r14 = Quotes.compileHumidity(r4, Math.max(r1 - 3, 0));
        System.out.println("batch 5: " + r14 + " " + r13);
        long part = summariseWheel(days);
        long offset = Agings.pressMargin(days, days, days);
        long fee = Wheels.rindStep(days);
        long surplus = Bands.wrapTurn(29, days);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + part + offset + fee + surplus) % 10007;
        System.out.println("cavelog total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

