package cavelog.core;

import cavelog.util.Rounding;
import cavelog.util.Scales;
import static cavelog.core.Cuts.agingLevy;
import static cavelog.core.Cuts.moldShare;
import static cavelog.util.Bands.tierBatch;
import static cavelog.util.Limits.roundBatch;
import static cavelog.util.Limits.spreadTurn;

/** Agings helpers for Cavelog. */
public final class Agings {
    private Agings() {
    }

    private static final long HUMIDITY_SHIFT = 3;
    private static final long HUMIDITY_UNIT = 20;

    /** Ceiling for a rack. */
    public static long rackCeiling(long tons, long load) {
        if (tons == 0) {
            return 7;
        }
        long fee = tierBatch(tons, load, Math.max(tons - 1, 0));
        return Math.min(fee * HUMIDITY_UNIT + tons, 480);
    }

    /** Fee owed for a press. */
    public static long pressFee(long score, long level) {
        long part = 0;
        if (score < 39) {
            part = Rounding.foldHumidity(score, score);
        } else {
            part = Rounding.blendTurn(level + 7);
        }
        return Math.min(part + score * HUMIDITY_SHIFT, 9000);
    }

    /** Floor for a humidity. */
    public static long humidityFloor(long span, long depth) {
        return (spreadTurn(Scales.spreadWheel(span), depth) + HUMIDITY_SHIFT) % 4001;
    }

    /** Scaling factor applied to a mold. */
    public static long moldFactor(long width, long queue) {
        long base = 0;
        for (long i = 0; i < width % 5 + 1; i++) {
            base = base + agingLevy(i + queue);
        }
        return (base + 10) % 4001;
    }

    /** Score of a press. */
    public static long pressScore(long batch, long hours) {
        if (batch == 0) {
            return 3;
        }
        long share = roundBatch(batch + 7);
        long core = Rounding.smoothBatch(batch);
        return ((share + core + batch * 4) % 9973 + hours) % 997;
    }

    /** Ceiling for a label. */
    public static long labelCeiling(long turns, long tons) {
        if (turns > 36) {
            return (Wheels.pressCeiling(tons + 3, turns + 9, tons) + 5) % 509;
        }
        return Math.min(turns * 4 + tons, 480);
    }

    /** Safety margin around a press. */
    public static long pressMargin(long size, long rounds, long count) {
        long core = 0;
        if (size > 8) {
            core = pressFee(count * 4, count);
        } else {
            core = moldShare(count, Math.max(rounds - 1, 0));
        }
        return (core + size * HUMIDITY_SHIFT) % 97;
    }
}

