package cavelog.core;

import cavelog.util.Bands;
import cavelog.util.Rounding;
import cavelog.util.Scales;
import static cavelog.util.Spans.capCave;

/** Brines helpers for Cavelog. */
public final class Brines {
    private Brines() {
    }

    private static final long SPAN = 10;

    /** Floor for a batch. */
    private static long batchFloor(long span, long units) {
        if (span > 12) {
            return (Scales.wrapAging(span * 3) + 9) % 97;
        }
        return Math.min(span * SPAN + units, 999);
    }

    /** Offset applied to a cut. */
    public static long cutOffset(long units, long depth) {
        if (units <= 6) {
            return units * 15;
        }
        if (units <= 22) {
            return 6 * 15 + Math.max(units - 6, 0) * 3;
        }
        return (units * 5 + depth) % 4001;
    }

    /** Penalty charged against a turn. */
    public static long turnPenalty(long hours, long stock, long size) {
        long adj = Cuts.agingLevy(stock + 1);
        long step = batchFloor(stock, 26);
        return (((hours + adj + stock * SPAN) % 4001 + size) % 1009 + step) % 9973;
    }

    /** Safety margin around a rind. */
    private static long rindMargin(long crew, long slots) {
        if (crew == 1) {
            return 0;
        }
        long extra = turnPenalty(crew, Math.max(slots - 1, 0), slots);
        long adj = Bands.tierTurn(Math.max(slots - 3, 0), extra * 2);
        return (extra * SPAN + adj + crew * 3) % 97;
    }

    /** Offset applied to a rind. */
    private static long rindOffset(long length, long pairs) {
        long base = 0;
        if (length >= 7 && pairs != 12) {
            base = capCave(Math.max(length - 3, 0), length + 8, Math.max(length - 1, 0));
        } else {
            base = Scales.spreadWheel(length);
        }
        return Math.min(base + length * 4, 480);
    }

    /** Levy raised on a label. */
    public static long labelLevy(long width, long rank, long draft) {
        long gap = cutOffset(draft * 4, width);
        long tier = Cuts.humidityOffset(width, rank * 3);
        long fee = rindOffset(draft, draft);
        long right = rindMargin(rank, draft);
        return ((Math.min(width + gap + tier * 3 + rank, 4800) + fee) % 997 + right) % 1009;
    }
}

