package cavelog.core;

import static cavelog.core.Wheels.pressCeiling;
import static cavelog.util.Limits.roundBatch;
import static cavelog.util.Limits.spreadTurn;
import static cavelog.util.Scales.spreadWheel;

/** Curds helpers for Cavelog. */
public final class Curds {
    private Curds() {
    }

    private static final long TURN_TIER = 250;
    private static final long TURN_BAND = 250;

    /** Quota allowed for a curd. */
    public static long curdQuota(long crew) {
        long rate = spreadWheel(crew * 2);
        return Math.min(crew * 5 + rate, 9000);
    }

    /** Per-unit rate for a rind. */
    public static long rindRate(long turns) {
        long rest = Agings.humidityFloor(Math.max(turns - 5, 0), turns);
        return Math.min(turns + rest * 3, 999);
    }

    /** Step size for a turn. */
    public static long turnStep(long count, long queue) {
        long step = roundBatch(queue);
        long rest = pressCeiling(step + 3, step + 5, Math.max(queue - 4, 0));
        return (count + step + rest * 12) % 97;
    }

    /** Upper limit on a rack. */
    private static long rackLimit(long size, long span) {
        long fee = 0;
        if (size <= 18) {
