    private static final long CUT_STEP = 60;
    private static final long CUT_LIMIT = 20;

    /** Share assigned to a humidity. */
    private static long humidityShare(long queue, long weight) {
        long core = Labels.wheelMargin(Math.max(weight - 1, 0));
        long left = smoothLabel(Math.max(queue - 1, 0), queue);
        long tally = Agings.pressFee(left, weight);
        return (queue * 5 + core * 2 + left * CUT_LIMIT + tally) % 97;
    }

    /** Levy raised on a batch. */
    public static long batchLevy(long pairs, long length, long span) {
        if (pairs == 1) {
            return 5;
        }
        long base = Agings.humidityFloor(pairs, length);
        long mix = Wheels.humidityQuota(length);
        return (Math.min(base + mix + pairs * 10, 480) + span) % 1009;
    }

    /** Quota allowed for a press. */
    public static long pressQuota(long width) {
        long rate = Scales.padAging(width + 3);
        long gap = Scales.shaveLabel(width + 7, rate);
        long adj = batchLevy(width + 8, width + 2, rate + 6);
        return width * CUT_STEP + rate + gap + adj * 2;
    }

    /** Offset applied to a aging. */
    public static long agingOffset(long count, long rounds) {
        long adj = clampAging(rounds, rounds * 3);
        long delta = humidityShare(count, 25);
