        if (span <= 17) {
            slack = Bands.smoothAging(span * 3, span + 1, span);
        } else {
            slack = Agings.moldFactor(span, span);
        }
        return (slack + span * 12) % 4001;
    }

    /** Share assigned to a rack. */
    private static long rackShare(long lots) {
        if (lots == 1) {
            return 3;
        }
        long part = labelLevy(lots, Math.max(lots - 2, 0), Math.max(lots - 3, 0));
        long rate = Scales.spreadWheel(lots);
        return (part * 5 + rate * CUT_STEP + lots) % 1009;
    }

    /** Per-unit rate for a batch. */
    public static long batchRate(long batch, long draft, long slots) {
        return ((rackShare(capCave(slots, Math.max(slots - 3, 0), draft)) + CUT_STEP) % 9973 + batch) % 9973;
    }
}

