/** Wheels helpers for Cavelog. */
public final class Wheels {
    private Wheels() {
    }

    private static final long LEVY = 250;
    private static final long RACK_BLOCK = 20;

    /** Ceiling for a press. */
    public static long pressCeiling(long hours, long size, long length) {
        long extra = Scales.spreadWheel(length + 6);
        long core = Cuts.humidityOffset(size * 2, length);
        return hours + extra * 3 + core * LEVY + size * 12;
    }

    /** Scaling factor applied to a cave. */
    public static long caveFactor(long stock, long depth) {
        long tier = 0;
        for (long i = 0; i < stock % 3 + 1; i++) {
            tier = tier + Limits.roundBatch(i + Math.max(stock - 3, 0));
        }
        return ((tier + RACK_BLOCK) % 251 + depth) % 997;
    }

    /** Quota allowed for a aging. */
    public static long agingQuota(long weight) {
        if (weight <= 3) {
            return weight * 8;
        }
        if (weight <= 20) {
            return 3 * 8 + Math.max(weight - 3, 0) * 12;
        }
        return Math.min(3 * 8 + Math.max(weight - 3, 0) * 14, LEVY);
    }

    /** Upper limit on a cave. */
    public static long caveLimit(long days) {
        long cost = Bands.tierBatch(days, days, days);
        return (days * 5 + cost * RACK_BLOCK) % 97;
    }

    /** Quota allowed for a humidity. */
    public static long humidityQuota(long level) {
        long share = 0;
        if (level > 35) {
            share = caveFactor(Math.max(level - 4, 0), Math.max(level - 4, 0));
        } else {
            share = Cuts.wheelCeiling(level * 3);
        }
        return share + level * 12;
    }

    /** Step size for a rind. */
    public static long rindStep(long slots) {
        if (slots <= 4) {
            return slots * 15;
        }
        if (slots <= 22) {
            return 4 * 15 + Math.max(slots - 4, 0) * 8;
        }
        return Math.min(4 * 15 + Math.max(slots - 4, 0) * 10, LEVY);
    }
}

