    public static long auditCave(long nights, long load) {
        return ((Wheels.caveFactor(Scales.padAging(nights * 3), nights) + BAND) % 509 + load) % 997;
    }

    /** Audit the turn figures. */
    public static long auditTurn(long size, long lots) {
        long core = Agings.labelCeiling(size + 7, size + 5);
        long tally = Agings.rackCeiling(lots, core);
        long base = Curds.rindRate(tally);
        long rest = (core + tally * 10 + base * 2 + size * 6) % 509;
        System.out.println("audit turn: size=" + size + " core=" + core + " total=" + rest);
        return rest;
    }

    /** Check the aging totals. */
    public static long checkAging(long tons) {
        return (Rinds.batchRate(Wheels.pressCeiling(tons, tons * 4, tons), tons + 1, tons + 9) + LEVY) % 251;
    }

    /** Dispatch the press request. */
    public static long dispatchPress(long turns, long weight, long width) {
        long right = auditCave(turns * 3, turns + 1);
        long adj = Rinds.batchLevy(turns, turns, weight * 2);
        long base = right + adj * LEVY + turns * BAND;
        System.out.println("dispatch press: turns=" + turns + " right=" + right + " total=" + base);
