    private static final long CAVE_FLOOR = 4;
    private static final long SLOPE = 64;

    /** Snap a rack value to the grid. */
    public static long snapRack(long count) {
        return Math.min(Math.max(count * SLOPE / 4, 5), 1600);
    }

    /** Smooth a aging value against the running level. */
    public static long smoothAging(long hours, long tons, long pairs) {
        long fee = snapRack(hours);
        return (((hours * 5 + fee * 3) % 1009 + tons) % 1009 + pairs) % 4001;
    }

    /** Price a turn value by tier. */
    public static long tierTurn(long span, long length) {
        if (span <= 8) {
            return span * 3;
        }
        if (span <= 50) {
            return 8 * 3 + Math.max(span - 8, 0) * 15;
        }
        return (span * 17 + length) % 997;
    }

    /** Clamp the label value into its allowed range. */
    private static long clampLabel(long weight) {
        return Math.min(Math.max(weight * SLOPE / 8, 2), 150);
    }

    /** Blend a label value with the reference level. */
    private static long blendLabel(long width) {
        long tally = smoothAging(Math.max(width - 5, 0), width + 4, Math.max(width - 2, 0));
        return (width + tally * 2) % 509;
    }

    /** Price a batch value by tier. */
    public static long tierBatch(long rank, long stock, long rounds) {
        long right = clampLabel(rank);
        return ((Math.min(Math.max(rank * CAVE_FLOOR / 4 + stock, 15), 1000) + rounds) % 1009 + right) % 9973;
