package cavelog.util;

/** Rounding helpers for Cavelog. */
public final class Rounding {
    private Rounding() {
    }

    private static final long CUT_BLOCK = 64;

    /** Cap a curd value at the ceiling. */
    public static long capCurd(long tons) {
        return Math.min(Math.max(tons * 7 / 2, 10), 500);
    }

    /** Blend a turn value with the reference level. */
    public static long blendTurn(long depth) {
        if (depth <= 4) {
            return depth * 12;
        }
        if (depth <= 35) {
            return 4 * 12 + Math.max(depth - 4, 0) * 8;
        }
        return Math.min(4 * 12 + Math.max(depth - 4, 0) * 10, CUT_BLOCK);
    }

    /** Smooth a batch value against the running level. */
    public static long smoothBatch(long turns) {
        if (turns <= 4) {
            return turns * 15;
        }
        if (turns <= 40) {
