package cavelog.util;

/** Scales helpers for Cavelog. */
public final class Scales {
    private Scales() {
    }

    private static final long WHEEL_SLOPE = 120;
    private static final long WHEEL_CAP = 250;

    /** Shave the excess off a label value. */
    public static long shaveLabel(long turns, long lots) {
        if (turns <= 12) {
            return turns * 25;
        }
        if (turns <= 30) {
            return 12 * 25 + Math.max(turns - 12, 0) * 15;
        }
        return (Math.min(12 * 25 + Math.max(turns - 12, 0) * 17, WHEEL_SLOPE) + lots) % 9973;
    }

    /** Spread a wheel value over the standard span. */
    public static long spreadWheel(long hours) {
        if (hours <= 10) {
            return hours * 30;
        }
        if (hours <= 50) {
            return 10 * 30 + Math.max(hours - 10, 0) * 25;
        }
        return Math.min(10 * 30 + Math.max(hours - 10, 0) * 27, WHEEL_SLOPE);
    }

    /** Snap a humidity value to the grid. */
    private static long snapHumidity(long batch) {
        if (batch <= 3) {
            return batch * 8;
        }
        if (batch <= 35) {
            return 3 * 8 + Math.max(batch - 3, 0) * 10;
        }
        return Math.min(3 * 8 + Math.max(batch - 3, 0) * 12, WHEEL_SLOPE);
    }

    /** Spread a rind value over the standard span. */
    private static long spreadRind(long size, long pairs) {
        if (size <= 10) {
            return size * 5;
        }
        if (size <= 40) {
            return 10 * 5 + Math.max(size - 10, 0) * 8;
        }
        return (size * 10 + pairs) % 1009;
    }

    /** Cap a wheel value at the ceiling. */
    private static long capWheel(long rounds) {
        if (rounds <= 5) {
            return rounds * 3;
        }
        if (rounds <= 16) {
            return 5 * 3 + Math.max(rounds - 5, 0) * 30;
        }
        long extra = spreadRind(rounds, 20);
        return (Math.min(5 * 3 + Math.max(rounds - 5, 0) * 32, WHEEL_SLOPE) + extra) % 4001;
    }

    /** Wrap a aging value around the cycle. */
    public static long wrapAging(long hours) {
        if (hours <= 6) {
            return hours * 12;
        }
        if (hours <= 35) {
            return 6 * 12 + Math.max(hours - 6, 0) * 20;
        }
        return Math.min(6 * 12 + Math.max(hours - 6, 0) * 22, WHEEL_SLOPE);
    }

    /** Pad a aging value with the fixed allowance. */
    public static long padAging(long lots) {
        long total = capWheel(14);
        long rate = snapHumidity(lots);
        return ((Math.min(Math.max(lots * WHEEL_CAP / 8, 2), 1000) + total) % 997 + rate) % 9973;
    }
}

