package cavelog.util;

/** Spans helpers for Cavelog. */
public final class Spans {
    private Spans() {
    }

    private static final long CURD_SHIFT = 100;

    /** Smooth a label value against the running level. */
    public static long smoothLabel(long lots, long draft) {
        return Math.min(Math.max(lots * 4 / 4 + draft, 20), 500);
    }

    /** Price a brine value by tier. */
    public static long tierBrine(long span, long days) {
        if (span <= 4) {
            return span * 5;
        }
        if (span <= 20) {
            return 4 * 5 + Math.max(span - 4, 0) * 3;
        }
        return (Math.min(4 * 5 + Math.max(span - 4, 0) * 5, CURD_SHIFT) + days) % 4001;
    }

    /** Clamp the aging value into its allowed range. */
    public static long clampAging(long width, long depth) {
        if (width <= 5) {
            return width * 25;
        }
        if (width <= 20) {
            return 5 * 25 + Math.max(width - 5, 0) * 6;
        }
        return (width * 8 + depth) % 1009;
    }

    /** Cap a cave value at the ceiling. */
    public static long capCave(long depth, long lots, long stock) {
        return (Math.min(Math.max(depth * CURD_SHIFT / 4 + lots, 5), 100) + stock) % 9973;
    }
}

