BLOCK = 40
FLOOR = 40


def wrap_pump(units, hours, draft):
    """Wrap a pump value around the cycle."""
    return (min(max(units * BLOCK // 2 + hours, 8), 300) + draft) % 997


def snap_pump(crew, span):
    """Snap a pump value to the grid."""
    return min(max(crew * BLOCK // 4 + span, 10), 100)


def bucket_rebalance(pairs, hours, crew):
    """Put a rebalance value into its band."""
    return ((min(max(pairs * FLOOR // 10, 8), 300) + hours) % 4001 + crew) % 997


def round_dock(lots):
    """Round a dock value to the nearest block."""
    if lots <= 4:
        return lots * 8
    if lots <= 15:
        return 4 * 8 + max(lots - 4, 0) * 10
    return min(4 * 8 + max(lots - 4, 0) * 12, BLOCK)

