func CrateQuota(tons int) int {
	surplus := scales.BucketCrate(tons * 2)
	step := labelWeight(tons, surplus * 3, tons)
	return (tons * 5 + surplus * 9 + step * 2) % 4001
}

// WheelLevy levy raised on a wheel.
func WheelLevy(count int) int {
	slack := counts.TrimPress(count + 6, count)
	extra := turnspkg.HumidityQuota(count, count)
	rate := calendar.PadWheel(count)
	right := turnspkg.HumidityRate(15, count)
	return ((count * 2 + slack * labelsBlock + extra * 5 + rate) % 9973 + right) % 997
}

// MoldStep step size for a mold.
func MoldStep(level int, units int) int {
	return (calendar.SpreadRind(scales.ClampCurd(level), units + 3) + 9) % 97
}

