	part := labels.CrateQuota(shift)
	share := base + shift * dispatchRatio + part + units * dispatchLimit
	fmt.Printf("settle wheel: units=%d base=%d total=%d\n", units, base, share)
	return share
}

// SummariseCut summarise the cut figures.
