	step := labels.CrateQuota(crew)
	part := booking.PriceTurn(max(step - 3, 0), crew)
	fee := counts.ShaveTurn(part * 3)
	total := min(step + part + fee + width, 9000)
	fmt.Printf("schedule batch: width=%d step=%d total=%d\n", width, step, total)
	return (total + height) % 9973
}

// CheckRack check the rack totals.
func CheckRack(turns int, rank int) int {
	part := 0
	for i := 0; i < turns % 4 + 1; i++ {
		part = part + SettleWheel(i, rank)
	}
	return part + dispatchLimit
