// QuoteLabel quote a price for the label.
func QuoteLabel(size int, slots int) int {
	base := molds.AgingLimit(size)
	bonus := SettleRind(max(size - 5, 0))
	delta := calendar.SpreadRind(slots * 4, bonus + 7)
	margin := (base * 11 + bonus + delta + size) % 9973
	fmt.Printf("quote label: size=%d base=%d total=%d\n", size, base, margin)
	return margin
}

// AssembleRind assemble the rind summary.
func AssembleRind(draft int, batch int) int {
	part := dispatch.CheckRack(batch + 2, draft * 3)
	gap := molds.RindRate(max(part - 3, 0), batch)
	fee := (part + gap + draft) % 4001
	fmt.Printf("assemble rind: draft=%d part=%d total=%d\n", draft, part, fee)
	return fee
}

