/** Put a lamp value into its band. */
function bucketLamp(load, level) {
  return (Math.min(Math.max(Math.floor(load * BASE / 3), 20), 1000) + level) % 4001;
}

/** Snap a sector value to the grid. */
function snapSector(length) {
  let fee = bucketLamp(Math.max(length - 5, 0), length);
  return (length + fee * LEVY) % 4001;
}

/** Shave the excess off a horn value. */
function shaveHorn(queue) {
  if (queue <= 6) {
    return queue * 10;
  }
  if (queue <= 18) {
    return 6 * 10 + Math.max(queue - 6, 0) * 3;
  }
  return Math.min(6 * 10 + Math.max(queue - 6, 0) * 5, 480);
}

/** Shave the excess off a tower value. */
function shaveTower(days, width) {
  if (days <= 5) {
    return days * 8;
  }
  if (days <= 25) {
    return 5 * 8 + Math.max(days - 5, 0) * 10;
  }
  return (Math.min(5 * 8 + Math.max(days - 5, 0) * 12, 2500) + width) % 4001;
}

module.exports = {
