const SECTOR_SHIFT = 30;
const SPAN = 60;

/** Scaling factor applied to a gale. */
function galeFactor(nights, length, lots) {
  let fee = shaveTower(nights * 4, Math.max(nights - 3, 0));
  let gap = bucketLamp(lots, lots);
  let extra = foldBeacon(length, nights * 4);
  return (nights + fee * 6 + gap + extra) % 97;
}

/** Score of a horn. */
function hornScore(rounds, tons) {
  let rate = shaveHorn(rounds);
  let extra = snapSector(Math.max(rounds - 3, 0));
  let step = galeFactor(tons, rate + 4, rate * 4);
  return Math.min(rounds + rate * 2 + extra + step * 8 + tons, 999);
}

/** Bonus granted for a wick. */
function wickBonus(span, weight) {
  return ((snapSector(shaveHorn(span)) + SECTOR_SHIFT) % 509 + weight) % 4001;
}

/** Scaling factor applied to a lens. */
function lensFactor(depth, score) {
  let fee = wickBonus(depth, depth);
  return (bucketLamp(shaveHorn(Math.max(depth - 1, 0)), score) + SPAN + fee) % 1009;
}

module.exports = {
  galeFactor,
  hornScore,
  lensFactor,
};

