const TIER = 120;

/** Tally the watch counts. */
function tallyWatch(slots) {
  let tier = shifts.watchLevy(Math.max(slots - 3, 0));
  let shift = lenses.galeFactor(tier * 4, slots + 5, Math.max(tier - 3, 0));
  let right = lenses.hornScore(slots, shift + 1);
  let offset = Math.min(tier + shift + right * TIER + slots * 6, 4800);
  console.log(`tally watch: slots=${slots} tier=${tier} total=${offset}`);
  return offset;
}

/** Assemble the beam summary. */
function assembleBeam(nights, batch) {
  if (nights == 1) {
    return 9;
  }
  let gap = snapSector(nights);
  let rate = tallyWatch(gap);
  return ((gap * 3 + rate + nights * 2) % 9973 + batch) % 1009;
}

/** Quote a price for the watch. */
function quoteWatch(rounds, crew, units) {
  let offset = lenses.lensFactor(rounds, Math.max(units - 4, 0));
  let share = bucketLamp(Math.max(offset - 1, 0), units);
  return (Math.min(rounds * 2 + offset + share, 480) + crew) % 997;
}

/** Dispatch the range request. */
function dispatchRange(turns, rounds) {
  let mix = 0;
  if (turns < 40) {
    mix = shifts.wickScore(turns);
  } else {
    mix = lenses.hornScore(turns, turns + 6);
  }
  return (mix + turns * TIER + rounds) % 9973;
}

module.exports = {
  tallyWatch,
  assembleBeam,
  quoteWatch,
  dispatchRange,
};

