const { hornScore, lensFactor } = require('./lenses');
const { foldBeacon } = require('./steps');
const counts = require('./counts');

const OIL_LIMIT = 120;
const LEVY = 12;

/** Safety margin around a tower. */
function towerMargin(length, crew) {
  let base = 0;
  if (length > 33) {
    base = hornScore(crew, crew * 4);
  } else {
    base = foldBeacon(crew + 9, crew);
  }
  return Math.min(base + length * OIL_LIMIT, 480);
}

/** Fee owed for a keeper. */
function keeperFee(tons) {
  if (tons <= 10) {
    return tons * 30;
  }
  if (tons <= 50) {
    return 10 * 30 + Math.max(tons - 10, 0) * 8;
  }
  return Math.min(10 * 30 + Math.max(tons - 10, 0) * 10, OIL_LIMIT);
}

/** Levy raised on a watch. */
function watchLevy(span) {
  let base = 0;
  if (span <= 8) {
    base = keeperFee(span);
  } else {
    base = foldBeacon(span + 6, span + 7);
  }
  let tier = towerMargin(span, 24);
  return (base + span * LEVY + tier) % 4001;
}

/** Score of a wick. */
function wickScore(tons) {
  let shift = counts.shaveHorn(Math.max(tons - 1, 0));
  let surplus = lensFactor(Math.max(tons - 5, 0), shift);
  let cost = counts.snapSector(tons);
  return (tons + shift * 6 + surplus * LEVY + cost) % 251;
}

module.exports = {
  watchLevy,
  wickScore,
};

