//! Cli helpers for Cavelog.

use crate::services::quotes::audit_rind;
use crate::services::dispatch;
use crate::services::forecast;
use crate::core::caves::turn_score;

/// Run the Cavelog report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = audit_rind(days);
    let r2 = dispatch::schedule_rack(r1 + 6);
    let r3 = forecast::dispatch_cave(r2, r2 * 4);
    println!("batch 1: {} {}", r3, r2);
    let r4 = forecast::schedule_cave(std::cmp::max(r3 - 2, 0));
    let r5 = forecast::price_aging(r2, r1 + 3);
    println!("batch 2: {} {}", r5, r4);
    let extra = turn_score(count);
    let total = (r1 + r2 + r3 + r4 + r5 + extra) % 10007;
    println!("cavelog total {} for {} days", total, days);
    return total;
}

