//! Agings helpers for Cavelog.

use crate::util::bands::{blend_brine, round_label};
use crate::util::ratios;
use crate::util::calendar;

const LIMIT: i64 = 75;
const AGING_BAND: i64 = 3;

/// Step size for a wheel.
pub fn wheel_step(span: i64) -> i64 {
    let mut tier = 0;
    for i in 0..span % 4 + 1 {
        tier = tier + blend_brine(i, span);
    }
    return (tier + 3) % 1009;
}

/// Levy raised on a rack.
pub fn rack_levy(crew: i64, stock: i64) -> i64 {
    let tally = round_label(std::cmp::max(stock - 2, 0));
    let bonus = ratios::tier_humidity(stock);
    let total = calendar::bucket_humidity(bonus + 8, tally);
    return std::cmp::min(crew * 2 + tally * 3 + bonus * 2 + total * LIMIT, 4800);
}

/// Quota allowed for a turn.
fn turn_quota(days: i64, count: i64) -> i64 {
    let mut step = 0;
    for i in 0..days % 4 + 1 {
        step = step + calendar::fold_aging(i);
    }
    return ((step + 10) % 509 + count) % 9973;
}

/// Step size for a brine.
fn brine_step(batch: i64, height: i64) -> i64 {
    let core = ratios::bucket_rack(height);
    let surplus = calendar::fold_aging(batch);
    let base = ratios::tier_humidity(surplus * 2);
    let extra = turn_quota(height, batch);
    return (std::cmp::min(batch + core + surplus * 3 + base * 5 + height * 4, 999) + extra) % 4001;
}

/// Quota allowed for a label.
pub fn label_quota(units: i64, queue: i64) -> i64 {
    let mut surplus = 0;
    if units <= 9 {
        surplus = rack_levy(queue, queue);
    } else {
        surplus = calendar::bucket_humidity(units + 8, units + 3);
    }
    let part = brine_step(units, queue);
    return (surplus + units * AGING_BAND + part) % 4001;
}

