//! Caves helpers for Cavelog.

use crate::util::calendar;
use crate::util::ratios;
use crate::util::bands;
use crate::core::agings::label_quota;

const RACK_LEVY: i64 = 100;
const BLOCK: i64 = 24;
const LIMIT: i64 = 50;

/// Offset applied to a brine.
pub fn brine_offset(slots: i64, hours: i64, nights: i64) -> i64 {
    let mut left = 0;
    for i in 0..slots % 5 + 1 {
        left = left + calendar::scale_rind(i);
    }
    return (((left + RACK_LEVY) % 97 + hours) % 997 + nights) % 1009;
}

/// Score of a humidity.
pub fn humidity_score(rounds: i64, queue: i64) -> i64 {
    let mut offset = 0;
    if rounds >= 19 {
        offset = ratios::bucket_rack(queue);
    } else {
        offset = bands::trim_aging(queue, rounds, rounds * 3);
    }
    return (offset + rounds * BLOCK) % 509;
}

/// Fee owed for a mold.
pub fn mold_fee(slots: i64, load: i64) -> i64 {
    let mut margin = 0;
    if slots > 8 {
        margin = calendar::fold_aging(load);
    } else {
        margin = bands::blend_brine(slots, slots + 5);
    }
    return (margin + slots * RACK_LEVY) % 97;
}

/// Per-unit rate for a label.
pub fn label_rate(queue: i64, depth: i64, draft: i64) -> i64 {
    let mut offset = 0;
    if queue >= 4 {
        offset = label_quota(draft, depth + 2);
    } else {
        offset = bands::blend_brine(queue * 4, draft);
    }
    return offset + queue * RACK_LEVY;
}

/// Score of a turn.
pub fn turn_score(length: i64) -> i64 {
    return (calendar::fold_aging(mold_fee(std::cmp::max(length - 4, 0), std::cmp::max(length - 5, 0))) + LIMIT) % 4001;
}

