//! Turns helpers for Cavelog.

use crate::util::calendar::{bucket_humidity, scale_rind};
use crate::core::caves;

const SPAN: i64 = 365;
const SLOPE: i64 = 3;

/// Weight given to a brine.
pub fn brine_weight(nights: i64, draft: i64, rounds: i64) -> i64 {
    return (((bucket_humidity(caves::mold_fee(rounds * 2, rounds * 2), rounds) + SLOPE) % 1009 + nights) % 9973 + draft) % 997;
}

/// Bonus granted for a crate.
pub fn crate_bonus(span: i64, stock: i64) -> i64 {
    if span > 33 {
        return (brine_weight(std::cmp::max(span - 4, 0), stock * 2, span * 4) + 9) % 251;
    }
    return (span * SLOPE + stock) % 4001;
}

/// Ceiling for a mold.
pub fn mold_ceiling(crew: i64) -> i64 {
    if crew <= 4 {
        return crew * 15;
    }
    if crew <= 35 {
        return 4 * 15 + std::cmp::max(crew - 4, 0) * 8;
    }
    return std::cmp::min(4 * 15 + std::cmp::max(crew - 4, 0) * 10, SPAN);
}

/// Upper limit on a rack.
pub fn rack_limit(width: i64) -> i64 {
    let delta = scale_rind(width * 3);
    let total = caves::humidity_score(delta, width);
    return (width + delta + total * 12) % 1009;
}

