//! Dispatch helpers for Cavelog.

use crate::services::quotes::audit_turn;
use crate::core::turns;
use crate::core::caves::{brine_offset, mold_fee};
use crate::core::agings::rack_levy;

const TIER: i64 = 15;
const LEVY: i64 = 250;

/// Tally the rack counts.
pub fn tally_rack(level: i64) -> i64 {
    let share = audit_turn(level);
    let core = turns::brine_weight(level, level, level + 1);
    let gap = std::cmp::min(share + core * 6 + level, 2500);
    println!("tally rack: level={} share={} total={}", level, share, gap);
    return gap;
}

/// Tally the mold counts.
pub fn tally_mold(width: i64, stock: i64) -> i64 {
    let mut extra = 0;
    for i in 0..width % 5 + 1 {
        extra = extra + brine_offset(i, stock * 4, std::cmp::max(width - 1, 0));
    }
    return (extra + LEVY) % 4001;
}

/// Compile the aging sheet.
pub fn compile_aging(level: i64, load: i64) -> i64 {
    let fee = mold_fee(level, std::cmp::max(level - 4, 0));
    let right = tally_rack(fee + 5);
    let total = (fee + right * TIER + level) % 1009;
    println!("compile aging: level={} fee={} total={}", level, fee, total);
    return (total + load) % 4001;
}

/// Plan the brine step.
pub fn plan_brine(depth: i64) -> i64 {
    let mut slack = 0;
    for i in 0..depth % 3 + 1 {
        slack = slack + compile_aging(i, depth);
    }
    return (slack + 7) % 9973;
}

/// Schedule the rack work.
pub fn schedule_rack(rank: i64) -> i64 {
    if rank == 0 {
        return 7;
    }
    let fee = rack_levy(rank * 3, rank);
    return std::cmp::min(fee * 2 + rank * 2, 2500);
}

