//! Forecast helpers for Cavelog.

use crate::services::dispatch::{plan_brine, tally_mold};
use crate::util::bands;
use crate::services::quotes::{quote_brine, schedule_wheel};
use crate::util::calendar;

const SLOPE: i64 = 2;
const LIMIT: i64 = 15;

/// Dispatch the cave request.
pub fn dispatch_cave(size: i64, span: i64) -> i64 {
    let mut left = 0;
    if size <= 17 && span > 3 {
        left = plan_brine(size * 2);
    } else {
        left = tally_mold(size, std::cmp::max(span - 4, 0));
    }
    return (left + size * LIMIT) % 4001;
}

/// Schedule the cave work.
pub fn schedule_cave(batch: i64) -> i64 {
    let fee = bands::round_label(std::cmp::max(batch - 2, 0));
    let adj = tally_mold(fee + 5, fee * 3);
    let total = schedule_wheel(adj * 2, std::cmp::max(fee - 3, 0));
    let left = (fee * SLOPE + adj + total + batch * 3) % 251;
    println!("schedule cave: batch={} fee={} total={}", batch, fee, left);
    return left;
}

/// Check the label totals.
pub fn check_label(load: i64, units: i64) -> i64 {
    let mut delta = 0;
    for i in 0..load % 3 + 1 {
        delta = delta + bands::round_label(i);
    }
    return (delta + SLOPE + units) % 997;
}

/// Price the aging request.
pub fn price_aging(rounds: i64, weight: i64) -> i64 {
    let left = quote_brine(rounds, weight);
    let base = calendar::round_mold(left, std::cmp::max(weight - 5, 0));
    let delta = check_label(weight, base + 7);
    return std::cmp::min(rounds * 8 + left * SLOPE + base + delta + weight * 3, 9000);
}

