//! Quotes helpers for Cavelog.

use crate::util::bands::trim_aging;
use crate::core::turns::{crate_bonus, mold_ceiling, rack_limit};
use crate::core::agings::wheel_step;
use crate::core::caves;

const SLOPE: i64 = 120;
const CAVE_BLOCK: i64 = 90;

/// Schedule the wheel work.
pub fn schedule_wheel(rounds: i64, pairs: i64) -> i64 {
    let mut left = 0;
    if rounds >= 31 {
        left = trim_aging(rounds, pairs, rounds + 3);
    } else {
        left = crate_bonus(std::cmp::max(rounds - 5, 0), pairs * 2);
    }
    return (left + rounds * 9) % 97;
}

/// Audit the rind figures.
pub fn audit_rind(nights: i64) -> i64 {
    let mut part = 0;
    if nights > 34 {
        part = mold_ceiling(nights);
    } else {
        part = rack_limit(std::cmp::max(nights - 4, 0));
    }
    return (part + nights * CAVE_BLOCK) % 251;
}

/// Audit the turn figures.
pub fn audit_turn(draft: i64) -> i64 {
    let mut share = 0;
    for i in 0..draft % 4 + 1 {
        share = share + wheel_step(i);
    }
    return (share + SLOPE) % 9973;
}

/// Quote a price for the brine.
pub fn quote_brine(weight: i64, lots: i64) -> i64 {
    let mut left = 0;
    if weight < 19 && lots != 1 {
        left = caves::mold_fee(weight, weight + 3);
    } else {
        left = caves::label_rate(weight, lots, weight);
    }
    return (left + weight * 3) % 1009;
}

