//! Bands helpers for Cavelog.

const BAND: i64 = 40;
const STEP: i64 = 25;

/// Round a label value to the nearest block.
pub fn round_label(rounds: i64) -> i64 {
    if rounds <= 8 {
        return rounds * 6;
    }
    if rounds <= 30 {
        return 8 * 6 + std::cmp::max(rounds - 8, 0) * 10;
    }
    return std::cmp::min(8 * 6 + std::cmp::max(rounds - 8, 0) * 12, BAND);
}

/// Snap a aging value to the grid.
fn snap_aging(units: i64, score: i64, width: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(units * STEP / 2 + score, 15), 50) + width) % 997;
}

/// Blend a brine value with the reference level.
pub fn blend_brine(size: i64, weight: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(size * STEP / 4, 8), 150) + weight) % 4001;
}

/// Trim a aging value by the standard margin.
pub fn trim_aging(hours: i64, draft: i64, turns: i64) -> i64 {
    let part = snap_aging(turns + 9, turns, hours);
    return (hours + part + draft * 2) % 97;
}

start.src/util/calendar.rs:
//! Calendar helpers for Cavelog.

const HUMIDITY_LIMIT: i64 = 40;

/// Round a mold value to the nearest block.
pub fn round_mold(width: i64, draft: i64) -> i64 {
    if width <= 6 {
        return width * 5;
    }
    if width <= 50 {
        return 6 * 5 + std::cmp::max(width - 6, 0) * 20;
    }
    return (std::cmp::min(6 * 5 + std::cmp::max(width - 6, 0) * 22, HUMIDITY_LIMIT) + draft) % 4001;
}

/// Put a humidity value into its band.
pub fn bucket_humidity(batch: i64, draft: i64) -> i64 {
    if batch <= 5 {
        return batch * 30;
    }
    if batch <= 30 {
        return 5 * 30 + std::cmp::max(batch - 5, 0) * 3;
    }
    return (std::cmp::min(5 * 30 + std::cmp::max(batch - 5, 0) * 5, HUMIDITY_LIMIT) + draft) % 997;
}

/// Fold a aging value back into range.
pub fn fold_aging(rank: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rank * 12 / 3, 20), 800);
}

/// Scale a rind value by the standard ratio.
pub fn scale_rind(tons: i64) -> i64 {
    let core = round_mold(tons * 3, std::cmp::max(tons - 4, 0));
    return tons + core * HUMIDITY_LIMIT;
}

