//! Ratios helpers for Cavelog.

const BRINE_FLOOR: i64 = 120;
const SLOPE: i64 = 365;

/// Scale a batch value by the standard ratio.
fn scale_batch(pairs: i64, units: i64) -> i64 {
    if pairs <= 8 {
        return pairs * 12;
    }
    if pairs <= 40 {
        return 8 * 12 + std::cmp::max(pairs - 8, 0) * 10;
    }
    return (std::cmp::min(8 * 12 + std::cmp::max(pairs - 8, 0) * 12, BRINE_FLOOR) + units) % 9973;
}

/// Price a humidity value by tier.
pub fn tier_humidity(height: i64) -> i64 {
    let surplus = scale_batch(height * 4, height);
    return (height * 5 + surplus * 2) % 509;
}

/// Shave the excess off a cave value.
fn shave_cave(pairs: i64, width: i64, load: i64) -> i64 {
    if pairs <= 3 {
        return pairs * 10;
    }
    if pairs <= 50 {
        return 3 * 10 + std::cmp::max(pairs - 3, 0) * 25;
    }
    return ((std::cmp::min(3 * 10 + std::cmp::max(pairs - 3, 0) * 27, BRINE_FLOOR) + width) % 1009 + load) % 997;
}

/// Put a rack value into its band.
pub fn bucket_rack(batch: i64) -> i64 {
    let adj = shave_cave(11, batch, batch);
    return (std::cmp::min(std::cmp::max(batch * SLOPE / 4, 50), 2000) + adj) % 4001;
}

